{
  "decisions": [
    {
      "requirement_id": "KMU-001",
      "methods": [
        "Test"
      ],
      "rationale": "Sistemin e-Devlet entegrasyonu ile oturum açma işlevinin çalışıp çalışmadığı, gerçek bir kullanıcı girişi yapılarak gözlemlenerek doğrulanabilir."
    },
    {
      "requirement_id": "KMU-002",
      "methods": [
        "Test"
      ],
      "rationale": "15 dakikalık bekleme süresinin sonunda oturumun sonlandırılması ve yönlendirme davranışı, zamanlayıcı testleri ile sistemin çalıştırılması üzerinden doğrulanabilir."
    },
    {
      "requirement_id": "KMU-003",
      "methods": [
        "Test"
      ],
      "rationale": "Art arda 5 başarısız giriş denemesi sonrası hesap kilitleme mekanizması, senaryo tabanlı testler ile sistemin tepkisi gözlemlenerek doğrulanabilir."
    },
    {
      "requirement_id": "KMU-004",
      "methods": [
        "Test"
      ],
      "rationale": "Dosya türü, boyut limiti ve adet kısıtlarının uygulanıp uygulanmadığı, farklı senaryolarda dosya yükleme işlemleri gerçekleştirilerek test edilebilir."
    },
    {
      "requirement_id": "KMU-005",
      "methods": [
        "Test"
      ],
      "rationale": "Başvuru tamamlanması sonrası benzersiz numara üretimi ve e-posta gönderimi, uçtan uca test senaryoları ile doğrulanabilir."
    },
    {
      "requirement_id": "KMU-006",
      "methods": [
        "Test"
      ],
      "rationale": "Taslak kaydetme ve 30 gün içinde devam etme işlevi, farklı zaman dilimlerinde oturum açarak sistemin davranışı gözlemlenerek test edilebilir."
    },
    {
      "requirement_id": "KMU-007",
      "methods": [
        "İnceleme"
      ],
      "rationale": "WCAG 2.1 AA uyumluluğu, otomatik tarama araçları ve manuel denetimler ile arayüz kodunun ve tasarımının gözle incelenmesi yoluyla doğrulanır."
    },
    {
      "requirement_id": "KMU-008",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Verilerin yalnızca Türkiye sınırları içindeki sunucularda saklanması, altyapı yapılandırma belgeleri ve sunucu konum bilgileri incelenerek doğrulanabilir."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "SW-001",
      "methods": [
        "Test"
      ],
      "rationale": "Gereksinim, belirli bir girdi (geçersiz belirteç) verildiğinde sistemin gözlemlenebilir davranışını (HTTP 401 yanıtı) tanımladığı için test ile doğrulanmalıdır."
