    {
      "requirement_id": "SW-002",
      "methods": [
        "Test"
      ],
      "rationale": "Rol tabanlı erişim kontrolünün doğru çalışıp çalışmadığı, farklı rollerle istekler göndererek ve HTTP 403 yanıtını gözlemleyerek test edilebilir."
    },
    {
      "requirement_id": "SW-003",
      "methods": [
        "Test"
      ],
      "rationale": "Hız sınırlama mekanizmasının etkinliği, belirli bir istemciye hızlıca çok sayıda istek göndererek ve HTTP 429 yanıtı ile Retry-After başlığının varlığını gözlemleyerek test edilebilir."
    },
    {
      "requirement_id": "SW-004",
      "methods": [
        "Analiz"
      ],
      "rationale": "Yük altında 99. persentil gecikme metriklerinin doğrulanması, performans testleri ve istatistiksel analiz gerektirdiği için analiz yöntemi uygundur."
    },
    {
      "requirement_id": "SW-005",
      "methods": [
        "Test"
      ],
      "rationale": "Zaman aşımı davranışı, arka uç servisin yanıt vermesini engelleyerek veya geciktirerek ve HTTP 504 yanıtının üretilip üretilmediğini gözlemleyerek test edilebilir."
    },
    {
      "requirement_id": "SW-006",
      "methods": [
        "Test"
      ],
      "rationale": "Yeniden başlatma olmadan yapılandırma değişikliğinin uygulanması ve devam eden isteklerin düşmemesi, canlı sistem üzerinde yapılandırma değiştirilerek ve istek akışı izlenerek test edilebilir."
    },
    {
      "requirement_id": "SW-007",
      "methods": [
        "Test"
      ],
      "rationale": "Günlük kayıtlarının içeriğinin doğrulanması, istekler gönderildikten sonra günlük dosyalarının veya akışlarının gözlemlenerek ve beklenen alanların varlığı kontrol edilerek test edilebilir."
    },
    {
      "requirement_id": "SW-008",
      "methods": [
        "Analiz"
      ],
      "rationale": "Aylık kullanılabilirlik yüzdesinin hesaplanması, uzun süreli izleme verilerinin istatistiksel analizi gerektirdiği için analiz yöntemi uygundur."
    }
  ]
}

